export function flightMotionAt(seconds){
 const index=Math.max(0,Math.min(frames.length-1,seconds*120)),i=Math.floor(index),a=frames[i],b=frames[Math.min(i+1,frames.length-1)],u=index-i;
 const values=a.map((n,k)=>n+(b[k]-n)*u);
 return {source:values[0],pitch:values[1],roll:values[2],fov:values[3],swing:values[4],recoil:values[5]};
}
